118.body:
Examples: h5v.commands.register({ id = "analysis.refresh", title = "Refresh analysis", summary = "Refresh plugin output", run = function(ctx) ctx.toast.info("refreshing") end,
}) h5v.events.on(h5v.ids.events.file_opened, function(ctx, event) ctx.log.info("opened " .. event.path)
end) h5v.ui.content_modes.register({ id = "analysis.results", title = "Analysis", render = function(ctx, ui) ui.block({ title = "Analysis" }, function(ui) ui.kv("selected", ctx.selection.path or "/") end) end,
}) h5v.themes.register({ id = "analysis.theme", title = "Analysis theme", variant = "dark", colors = { [h5v.ids.colors.content.app_brand] = "#7dd3fc", },
}) h5v.events.on(h5v.ids.events.file_opened, function(ctx, event) local exe = ctx.process.command_path("h5v") or "h5v" local help = ctx.process.run({ command = { exe, "--help" } }) if help.success then ctx.plugin.store.set("help_text", help.stdout or "") else ctx.log.warning("failed to capture help for " .. event.path) end
end) h5v.mchart.functions.register({ id = "analysis.scale", name = "scale", params = { { name = "series", kind = h5v.ids.value_kinds.series }, { name = "factor", kind = h5v.ids.value_kinds.scalar }, }, returns = h5v.ids.value_kinds.series, eval = function(series, factor) return series * factor end,
}) Built-in events cover file lifecycle plus runtime transitions such as selection changes, mode/focus changes, tree visibility changes, and help/logs/search/command/mchart open-close hooks. Use h5v.ids.events.* and the in-app help for the current event list.

